"""Level background art (your painted sky, mountains, hills/village and ground strip). Layers are mirror-joined so they tile forever.
img(name) gives the surface; scaled(name, w, h) a cached resized copy."""
import base64
import io
import pygame

# where each layer goes on the 600-pixel-high screen (top y) and how fast it scrolls
FAR_Y, MID_Y = 296, 400        # (the ground strip is placed by the game at the ground line)
GROUND_GRASS = 34              # rows above the grass line in lvl_ground.png (tufts and flowers)
PNG = {
  'lvl_far': ('png', ''),
  'lvl_ground': ('png', ''),
  'lvl_mid': ('png', ''),
  'lvl_sky_day': ('jpg', ''),
  'lvl_sky_night': ('jpg', ''),
}
_C = {}


def has(name):
  return name in PNG


def img(name):
  s = _C.get(name)
  if s is None:
    ext, data = PNG[name]
    s = pygame.image.load(io.BytesIO(base64.b64decode(data)), 'art.' + ext)
    try:
      s = s.convert_alpha()
    except Exception:
      pass
    _C[name] = s
  return s


def scaled(name, w, h, smooth=True):
  k = (name, int(w), int(h))
  s = _C.get(k)
  if s is None:
    src = img(name)
    fn = getattr(pygame.transform, 'smoothscale', None) if smooth else None
    try:
      s = (fn or pygame.transform.scale)(src, (max(1, int(w)), max(1, int(h))))
    except Exception:
      s = pygame.transform.scale(src, (max(1, int(w)), max(1, int(h))))
    _C[k] = s
  return s
